def binary_search(arr: list, target: int) -> int:
    # right 初始值应为 len(arr) - 1，保证搜索区间为闭区间 [left, right]
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

