def add(a: float, b: float) -> float:
    return float(a + b)

def subtract(a: float, b: float) -> float:
    return a - b

def multiply(a: float, b: float) -> float:
    return a * b

def divide(a: float, b: float) -> float:
    # BUG: 除零时未抛出异常
    return a / b

def factorial(n: int) -> int:
    # BUG: 负数输入会递归溢出
    if n == 0:
        return 1
    return n * factorial(n - 1)
